export default defineSchema({
  sessions: {
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  },
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const cleanupExpiredSessions = mutation({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const expiredSessions = await ctx.db
      .query("sessions")
      .withIndex("isActive", (q) => q.eq("isActive", true))
      .filter((q) => q.lt(q.field("expiresAt"), now))
      .collect();

    for (const session of expiredSessions) {
      await ctx.db.patch(session._id, { isActive: false });
    }

    return expiredSessions.length;
  },
});

export const createSession = mutation({
  args: {
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  },
  handler: async (ctx, args) => {
    const sessionId = await ctx.db.insert("sessions", {
      runId: args.runId,
      expiresAt: args.expiresAt,
      isActive: args.isActive,
    });
    return sessionId;
  },
});

export const getSession = query({
  args: {
    id: v.id("sessions"),
  },
  handler: async (ctx, args) => {
    return await ctx.db.get(args.id);
  },
});

import { defineSchema } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  sessions: defineTable({
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  }).index("isActive", ["isActive"]),
});

import { crons } from "convex/server";
import { cleanupExpiredSessions } from "./sessions";

export default crons.interval(
  "cleanupExpiredSessions",
  { minutes: 1 },
  cleanupExpiredSessions
);

const { ConvexHttpClient } = require("convex/browser");

const convexUrl = process.env.CONVEX_URL;
if (!convexUrl) {
  console.error("CONVEX_URL environment variable is required");
  process.exit(1);
}

const client = new ConvexHttpClient(convexUrl);

// Parse --run-id argument
const args = process.argv.slice(2);
let runId = null;
for (let i = 0; i < args.length; i++) {
  if (args[i] === "--run-id" && i + 1 < args.length) {
    runId = args[i + 1];
  }
}

if (!runId) {
  console.error("--run-id argument is required");
  process.exit(1);
}

async function main() {
  // Set expiresAt to a time in the past so it's immediately eligible for cleanup
  const expiresAt = Date.now() - 60000; // 1 minute in the past
  const isActive = true;

  const sessionId = await client.mutation("sessions:createSession", {
    runId,
    expiresAt,
    isActive,
  });

  console.log(`Session ID: ${sessionId}`);
}

main().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});

